/* @lc app=leetcode id=3017 lang=kotlin */
class Solution { fun countOfPairs(n: Int, x: Int, y: Int): LongArray = minOf(x, y).let { c0 -> maxOf(x, y).let { c1 -> LongArray(n + 2).also { A -> (1..n).forEach { i -> A.also { it[0] += 2 }.also { it[minOf(i - 1, Math.abs(i - c1) + c0)]-- }.also { it[minOf(n - i, Math.abs(i - c0) + 1 + n - c1)]-- }.also { it[minOf(Math.abs(i - c0), Math.abs(c1 - i) + 1)]++ }.also { it[minOf(Math.abs(i - c0) + 1, Math.abs(c1 - i))]++ }.also { it[maxOf(c0 - i, 0) + maxOf(i - c1, 0) + (c1 - c0) / 2]-- }.also { it[maxOf(c0 - i, 0) + maxOf(i - c1, 0) + (c1 - c0 + 1) / 2]-- } } }.also { A -> (1..n).forEach { i -> A[i] += A[i - 1] } }.copyOfRange(1, n + 1) } } }